import { Message } from "@arco-design/web-react";
import ajax from "@/utils/ajax";



class AI {


    /**
     * 多语言补全
     */
    multilingualCompletion = async (zhCNs: string[]) => {
        return ajax.post('/deepseek/interpreter', {
            content: zhCNs.join(',')
        }).then((res) => {
            try {
                const content = res.data;
                const jsonStr = content.slice(content.indexOf('['), content.lastIndexOf(']') + 1);
                const list = JSON.parse(jsonStr.replace(/(\n)/g,''));

                return list;
            }catch(e) {
                Message.error("AI 生成内容无法解析，请稍后再试～，或联系管理员")
                throw e;
            }
        });
        return ajax.post('https://api.b3n.fun/v1/chat/completions', {
            "model": "gpt-4o-mini",
            "max_tokens": 4096,
            "messages": [
              {
                "role": "user",
                "content": `[${zhCNs.join(',')}], 根据我上面数组中给的中文，生成以下对应的多语言Key（key 生成规则采用英文语意，只能使用小写字母，不要使用_使用.连接，例如a.b.c 这种） 和以下多语言翻译'zh-CN' | 'zh-TW' | 'zh-HK' | 'en-US' | 'de-DE' | 'fr-FR' | 'ru-RU' | 'ja-JP' | 'ko-KR' 。要返回给我字符串json 类型数据，数据格式例如 '[{ key: 'wjfajf', zhCN: '确认' }]'`
              }
            ]
        }, {
            headers: {
                Authorization: 'sk-LULdYg0W1qqLyXBh2934Ae8cF14d4801A42c42331d233aB1'
            }
        }).then((res) => {
            try {
                const { choices } = res;
                const { message } = choices[0];
                const { content } = message;
                const jsonStr = content.slice(content.indexOf('['), content.lastIndexOf(']') + 1);
                const list = JSON.parse(jsonStr.replace(/(\n)/g,''));

                return list;
            }catch(e) {
                Message.error("AI 生成失败，请稍后再试～")
                throw e;
            }
        });
    }
}


export default new AI();